import{_ as t,o,c as d,a3 as a}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse('{"title":"Handler protocol","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Handler protocol | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/handler-protocol"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/handler-protocol"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/handler-protocol"}]]},"headers":[],"relativePath":"catter/design/handler-protocol.md","filePath":"en/catter/design/handler-protocol.md","lastUpdated":1792896246000}'),r={name:"catter/design/handler-protocol.md"};function n(i,e,s,c,h,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="handler-protocol" tabindex="-1">Handler protocol <a class="header-anchor" href="#handler-protocol" aria-label="Permalink to &quot;Handler protocol&quot;">​</a></h1><p>This page specifies the protocol between catter and a <a href="./../scripting/handlers">handler</a>, for writing a handler without an SDK. The SDKs implement it, with types generated from the same definition catter&#39;s are.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to &quot;Transport&quot;">​</a></h2><p>Messages are <a href="https://www.jsonrpc.org/specification" target="_blank" rel="noreferrer">JSON-RPC 2.0</a>, each framed as the Language Server Protocol frames them: a <code>Content-Length: &lt;n&gt;</code> header, an empty line (<code>\\r\\n\\r\\n</code>), then <code>n</code> bytes of UTF-8 JSON.</p><ul><li>A handler catter starts (<code>--handler</code>) reads catter&#39;s messages on its stdin and writes its own on its stdout. Its stderr is the terminal&#39;s.</li><li>A handler that listens (<code>--connect</code>) does the same over each TCP connection: one connection is one session.</li></ul><p>catter sends requests and notifications; a handler answers the requests and sends nothing else. Beside the messages below, catter may send <code>$/cancelRequest</code>, as the Language Server Protocol does, for a request it no longer waits for: a handler may ignore it.</p><h2 id="a-session" tabindex="-1">A session <a class="header-anchor" href="#a-session" aria-label="Permalink to &quot;A session&quot;">​</a></h2><ol><li><code>initialize</code> (request): the session starts. The handler answers with what it wants to be told.</li><li>While the build runs, for each command: <code>command</code>, a request to a handler that decides and a notification to one that does not; <code>error</code> when catter could not capture a command; <code>exit</code> once a command has run. Notifications arrive only if the handler asked for them.</li><li><code>finish</code> (request): the build has ended. Once the handler has answered, catter ends its input: a handler it started then exits; over TCP, catter shuts down its side of the connection, and the handler closes it.</li></ol><p>Commands of a parallel build overlap: <code>command</code> requests can be in flight together, and are answered by their ids, in any order.</p><h2 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to &quot;Messages&quot;">​</a></h2><h3 id="initialize" tabindex="-1"><code>initialize</code> <a class="header-anchor" href="#initialize" aria-label="Permalink to &quot;`initialize`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>integer</td><td>The protocol&#39;s version: <code>1</code>.</td></tr><tr><td><code>session</code></td><td>string</td><td>Tells apart the sessions one handler serves over TCP.</td></tr><tr><td><code>mode</code></td><td>string</td><td>How commands are captured: <code>inject</code>, or <code>replay</code>.</td></tr><tr><td><code>build.command</code></td><td>OS string array</td><td>The build command.</td></tr><tr><td><code>build.cwd</code></td><td>OS string</td><td>Its working directory.</td></tr></tbody></table><p>The result:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>decides</code></td><td>boolean</td><td>Every command comes as a request, which the build waits for.</td></tr><tr><td><code>events.command</code></td><td>boolean</td><td>A handler that does not decide is told of each command.</td></tr><tr><td><code>events.error</code></td><td>boolean</td><td>The handler is told of the commands catter could not capture.</td></tr><tr><td><code>events.exit</code></td><td>boolean</td><td>The handler is told of each command&#39;s exit.</td></tr><tr><td><code>env</code></td><td>boolean</td><td>Commands carry their environment.</td></tr></tbody></table><h3 id="command" tabindex="-1"><code>command</code> <a class="header-anchor" href="#command" aria-label="Permalink to &quot;`command`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>The command&#39;s id in the session.</td></tr><tr><td><code>parent</code></td><td>integer, optional</td><td>The command that started it; absent for the build command.</td></tr><tr><td><code>cwd</code></td><td>OS string</td><td>Its working directory.</td></tr><tr><td><code>executable</code></td><td>OS string</td><td>The program it runs.</td></tr><tr><td><code>args</code></td><td>OS string array</td><td>Its arguments, the program&#39;s name first.</td></tr><tr><td><code>env</code></td><td>OS string array, optional</td><td>Its environment, <code>NAME=value</code> entries, if the handler asked.</td></tr></tbody></table><p>The result of the request is an action, named by its <code>action</code> field:</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>Fields</th><th>What catter does</th></tr></thead><tbody><tr><td><code>skip</code></td><td></td><td>Runs the command as it is.</td></tr><tr><td><code>drop</code></td><td></td><td>Does not run it: it exits 0.</td></tr><tr><td><code>abort</code></td><td><code>reason</code>: string</td><td>Ends the session (below), reporting the reason.</td></tr><tr><td><code>modify</code></td><td><code>args</code>, and optionally <code>executable</code>, <code>cwd</code>, <code>env</code></td><td>Runs the command with these in place of its own; a field left out keeps the command&#39;s.</td></tr></tbody></table><h3 id="error-exit-and-finish" tabindex="-1"><code>error</code>, <code>exit</code> and <code>finish</code> <a class="header-anchor" href="#error-exit-and-finish" aria-label="Permalink to &quot;`error`, `exit` and `finish`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Fields</th></tr></thead><tbody><tr><td><code>error</code></td><td><code>id</code>, <code>parent</code> (optional), <code>message</code>: why catter could not capture the command.</td></tr><tr><td><code>exit</code></td><td><code>id</code>, <code>code</code>: its exit code, <code>duration</code>: microseconds from the handler&#39;s decision on the command (its notification, to an observer) to its exit, in which the handlers after it in the chain decide.</td></tr><tr><td><code>finish</code></td><td><code>code</code>: the build&#39;s exit code. The result is <code>null</code>.</td></tr></tbody></table><h2 id="strings-and-numbers" tabindex="-1">Strings and numbers <a class="header-anchor" href="#strings-and-numbers" aria-label="Permalink to &quot;Strings and numbers&quot;">​</a></h2><ul><li><strong>OS strings.</strong> An argument, a path or an environment entry is a JSON string when its bytes are valid UTF-8, and <code>{&quot;base64&quot;: &quot;&lt;the bytes in base64&gt;&quot;}</code> otherwise: on Linux and macOS they are bytes, which need not be UTF-8. A handler hands such a value back as it got it, or builds one the same way.</li><li>Every other string is valid Unicode. JSON text has no byte order mark and no object repeats a key.</li><li>An optional field that is absent may be left out or be <code>null</code>.</li><li>Every integer of version 1 is below 2<sup>53</sup>, which a JavaScript number holds exactly.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>A handler that cannot answer a request answers with a JSON-RPC error; its <code>message</code> is what catter reports. catter ends the session when a handler answers with an error or with <code>abort</code>, stops (its output ends), writes what is not an answer to one of its requests, or does not answer within <code>--handler-timeout</code>: the command being decided, and every command the build starts after it, fail without running; once the build has ended, catter ends the handlers&#39; input without a <code>finish</code>, prints the reason and exits 1.</p><p>An observer cannot answer a notification: one that fails exits, which catter reports when it next writes to it.</p>',25)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
